        byte unsigned sb[]; logic [18:0] sf;
        busy_sof = 1; sf = 19'(sof_num[10:0]); sb = new[3]; sb[0] = pidb(4'h5); sb[1] = sf[7:0]; sb[2] = {crc5_field(sf, 11), sf[10:8]};
        phy_send_raw(sb, 3, -1); sof_num++; sof_sent++; idle_cnt = 0; busy_sof = 0;
      end
    end
  end

  always @(posedge clk_phy) if (pclk_auto && rst_n && !suspend_n) begin pclk_lo++; if (pclk_lo >= 8) pclk_on = 0; end else pclk_lo = 0;
  always @(posedge suspend_n) if (pclk_auto && !pclk_on) begin #(pclk_dly); pclk_on = 1; end
  // UTMILP-BEGIN a_susp_handoff (SVA-017, DEC-049): the wake request of the always-on m_usb2_utmilp falls only when the
  // synchronized engine request is 1 (hand-off) or, after a line wake, when the line is back at the stored idle value
  // (spurious wake); o_utmi_suspend_n has no pulse shorter than one CLK-BUS period.
  int act_handoff = 0, act_spur = 0, act_wake = 0; realtime sn_t = 0;
  always @(posedge clk_bus) if (rst_n) begin
    if (!dut.u_core.gen_utmi.u_utmilp.reg_wake && dut.u_core.gen_utmi.u_utmilp.w_wake_nxt) act_wake++;
    if (dut.u_core.gen_utmi.u_utmilp.reg_wake && !dut.u_core.gen_utmi.u_utmilp.w_wake_nxt) begin
      if (dut.u_core.gen_utmi.u_utmilp.w_susp_n_sync) act_handoff++;
      else if (dut.u_core.gen_utmi.u_utmilp.reg_wake_line &&
               dut.u_core.gen_utmi.u_utmilp.w_ls_sync == dut.u_core.gen_utmi.u_utmilp.reg_idle) act_spur++;
      else a_fail("a_susp_handoff", "wake request released while the engine is suspended and the line is not idle");
    end
  end
  always @(suspend_n) if (rst_n && $realtime > 0) begin
    if (sn_t > 0 && ($realtime - sn_t) < t_bus) a_fail("a_susp_handoff", $sformatf("o_utmi_suspend_n pulse of %0.1f ns", $realtime - sn_t));
    sn_t = $realtime;
  end
  // UTMILP-END

  // ------------------------------------------------------------------ mon_usb: packets from the DUT (transmit path of the link)
  byte unsigned cap [0:65535]; int cap_n = 0;
  byte unsigned q_pkt [$][]; realtime q_t0 [$]; int q_gap [$];
  int sof_cnt = 0; realtime sof_t_last = 0; real sof_min = 1e12, sof_max = 0; int sof_fn = -1, sof_seq_err = 0, sof_wrap = 0, sof_mark = 0, sof_mk2 = 0, sof_base = 0; bit keep_sof = 0; realtime sof_tref = 0, sof_tfirst = 0, t_mark = 0; bit sof_want = 0;
  logic txv_d = 0; realtime t_tx_start, t_tx_end = 0; int gap_cyc; int txready_low = 0;
  always @(posedge clk_phy) begin
    txv_d <= utmi_txvalid;
    utmi_txready <= (txready_low == 0) ? 1'b1 : (($urandom_range(0, 99) < txready_low) ? 1'b0 : 1'b1);
    if (utmi_txvalid && !txv_d) begin
      t_tx_start = $realtime; cap_n = 0;
      // gap to the end of the last received packet; without one, 100000 plus the gap to the end of the previous own packet (GAPB)
      gap_cyc = (t_rx_end > 0) ? int'(($realtime - t_rx_end) / T_PHY + 0.5) : ((t_tx_end > 0) ? 100000 + int'(($realtime - t_tx_end) / T_PHY + 0.5) : -1);
      if (utmi_rxactive) a_fail("a_utmi_tx", "transmit started while RXActive is high");
    end
    if (utmi_txvalid && utmi_txready) begin
      act_utmi_tx++;
      cap[cap_n] = utmi_dataout[7:0]; cap_n++;
      if (UTMI_W == 16 && utmi_txvalidh) begin cap[cap_n] = utmi_dataout[15:8]; cap_n++; end
    end
    if (!utmi_txvalid && txv_d) begin
      byte unsigned p[]; p = new[cap_n]; for (int i = 0; i < cap_n; i++) p[i] = cap[i];
      if (cap_n >= 3 && cap[0] == pidb(4'h5) && !keep_sof) begin            // SOF: checked here, not queued
        int fn; fn = {cap[2][2:0], cap[1]};
        if (crc5_field(19'(fn), 11) != cap[2][7:3]) begin errors++; $display("FAIL @%0t: SOF CRC5 wrong", $time); end
        if (sof_t_last > 0) begin
          real dt; dt = $realtime - sof_t_last; if (dt < sof_min) sof_min = dt; if (dt > sof_max) sof_max = dt;
        end
        // frame number sequence: the same number (the eight microframes of a frame) or the next one, modulo 2048
        if (sof_fn >= 0 && fn != sof_fn) begin
          if (fn == ((sof_fn + 1) & 11'h7FF)) begin if (sof_fn == 2047) sof_wrap++; end else sof_seq_err++;
        end
        if (sof_want) begin sof_tfirst = $realtime; sof_want = 0; end
        sof_t_last = $realtime; sof_cnt++; sof_fn = fn;
        if (sof_dbg) $display("SOF @%0t fn=%0d", $time, fn);
      end else begin
        if (nc_data && cap_n >= 4 && (cap[0] == pidb(4'h3) || cap[0] == pidb(4'hB) || cap[0] == pidb(4'h7) || cap[0] == pidb(4'hF))) begin
          byte unsigned pl[]; logic [15:0] c; pl = new[cap_n - 3]; p[1] = p[1] ^ 8'h01;
          for (int i = 0; i < cap_n - 3; i++) pl[i] = p[1 + i];
          c = ~crc16_rem(pl, cap_n - 3);
          for (int i = 0; i < 8; i++) begin p[cap_n - 2][i] = c[15 - i]; p[cap_n - 1][i] = c[7 - i]; end
          nc_data_n++;
        end
        nc_pkt_n++;
        if (!nc_silent) begin q_pkt.push_back(p); q_t0.push_back(t_tx_start); q_gap.push_back(gap_cyc); end
      end
      t_rx_end = 0; t_tx_end = $realtime;
    end
  end
  // a_utmi_tx: data stable while TXValid is high and TXReady is low
  logic [15:0] txd_d; logic txr_d = 1;
  always @(posedge clk_phy) begin
    txd_d <= utmi_dataout; txr_d <= utmi_txready;
    if (rst_n && txv_d && !txr_d && utmi_txvalid && utmi_dataout != txd_d) a_fail("a_utmi_tx", "data changed while TXReady was low");
  end
  // a_utmi_w16: the width pins follow PARA_USB2_UTMI_W (REQ-IF-002); a_utmi_mode: the mode pins change only while no packet is on
  // the bus (REQ-IF-012); a_irq_level: o_int_usb is the registered OR of the enabled status bits (REQ-IF-008)
  int act_utmi_w16 = 0, act_utmi_mode = 0, act_irq_lvl = 0;
  logic [1:0] opm_d = 0, xcv_d = 0; logic term_d = 0, dppd_d = 0, dmpd_d = 0; logic irq_exp = 0;
  always @(posedge clk_phy) if (rst_n) begin
    act_utmi_w16++; act_utmi_mode++;
    if (!$isunknown(db16_8) && db16_8 !== (UTMI_W == 16)) a_fail("a_utmi_w16", "UTMI+ data bus width pin does not follow PARA_USB2_UTMI_W");
    if (UTMI_W == 8 && utmi_txvalidh === 1'b1) a_fail("a_utmi_w16", "TXValidH high in 8-bit mode");
    if (utmi_txvalidh === 1'b1 && utmi_txvalid !== 1'b1) a_fail("a_utmi_w16", "TXValidH high without TXValid");
    if ((opmode !== opm_d || xcvrsel !== xcv_d || termsel !== term_d || dppd !== dppd_d || dmpd !== dmpd_d) && (utmi_txvalid === 1'b1 || utmi_rxactive))
      a_fail("a_utmi_mode", $sformatf("mode pins changed while a packet was on the bus: opmode %0d->%0d xcvr %0d->%0d term %0d->%0d pd %0d%0d->%0d%0d txvalid=%0b rxactive=%0b", opm_d, opmode, xcv_d, xcvrsel, term_d, termsel, dppd_d, dmpd_d, dppd, dmpd, utmi_txvalid, utmi_rxactive));
    opm_d <= opmode; xcv_d <= xcvrsel; term_d <= termsel; dppd_d <= dppd; dmpd_d <= dmpd;
  end
  // a_phy_row (2026-11-25, DEC-048): XcvrSelect, TermSelect, OpMode and the pull-downs always form a defined row of ULPI 1.1
  // Table 40 (reproduced in the Microchip USB3320 data sheet DS00001792E Table 5-1; the USB3500 UTMI+ data sheet has the same rows):
  // OpMode 11b never; while SuspendM is low only a suspend row (full- or low-speed transceiver, TermSelect 1, OpMode 00b). The
  // device row 00/0/10 (Test_J/Test_K of a device, USB 2.0 7.1.20) is accepted although the table lists it for the host only.
  int act_phy_row = 0, phy_row_wait = 0;
  // Line-state model of op LSR (2026-11-25): while ls_auto is set the line follows the PHY row like the resistor network does:
  // SE0 under the host high-speed terminations, otherwise the idle state of the attached device (ls_dev 1: pull-up on D+ = J,
  // 2: pull-up on D- = K in full-speed terms); op LS hands the line back to the scenario.
  bit ls_auto = 0; int ls_dev = 1;
  always @(posedge clk_phy) if (ls_auto)
    utmi_linestate <= (xcvrsel == 2'b00 && !termsel && opmode != 2'b01 && dppd && dmpd) ? 2'b00 : ((ls_dev == 2) ? 2'b10 : 2'b01);
  function automatic bit phy_row_ok(logic [1:0] x, logic t, logic [1:0] o, logic pdp, logic pdm, logic sn);
    if (o == 2'b01) return 1'b1;                                   // tri-state drivers (non-driving), any setting
    if (o == 2'b11 || pdp != pdm) return 1'b0;
    if (!sn) return (x == 2'b01 || x == 2'b10) && t && (o == 2'b00);
    if (pdp) return (x == 2'b00 && !t) || (x[0] && t && o == 2'b00) || (x == 2'b01 && t && o == 2'b10) || (x == 2'b10 && t) ||
                    (x == 2'b01 && !t && o == 2'b00);                // host rows; the last one is power-up
    return (x == 2'b00 && t && o == 2'b10) || (x == 2'b00 && !t) || ((x == 2'b01 || x == 2'b10) && t);   // peripheral rows
  endfunction
  always @(posedge clk_phy) begin
    if (!rst_n) phy_row_wait <= 0;
    else if (phy_row_wait < 8) phy_row_wait <= phy_row_wait + 1;     // the mode registers load in the first cycles after reset
    else if (!$isunknown({xcvrsel, termsel, opmode, dppd, dmpd, suspend_n})) begin
      act_phy_row++;
      if (!phy_row_ok(xcvrsel, termsel, opmode, dppd, dmpd, suspend_n))
        a_fail("a_phy_row", $sformatf("undefined PHY row xcvr %b term %b opmode %b pd %b%b suspend_n %b", xcvrsel, termsel, opmode, dppd, dmpd, suspend_n));
    end
  end
  always @(posedge clk_bus) if (rst_n) begin
    act_irq_lvl++;
    if (int_usb !== irq_exp) a_fail("a_irq_level", "o_int_usb is not the registered OR of the enabled status bits");
    irq_exp <= |(dut.u_core.u_regs.u_irq.i_raw & dut.u_core.u_regs.u_irq.i_en);
  end else irq_exp <= 1'b0;
  int last_gap = -1;
  task automatic get_pkt(input int tmo, output bit got, output byte unsigned p[]);
    int t; t = 0; got = 0;
    while (q_pkt.size() == 0 && t < tmo) begin @(posedge clk_phy); t++; end
    if (q_pkt.size() != 0) begin p = q_pkt.pop_front(); void'(q_t0.pop_front()); last_gap = q_gap.pop_front(); got = 1; end
  endtask

  // chk_irq: sampled interrupt output for the IRQ operation
  // chk_watchdog
  longint wd_limit = 64'd4_000_000_000;      // ns
  initial begin
    forever begin #1000000; if ($time > wd_limit) begin errors++; $display("FAIL @%0t: watchdog timeout", $time); finish_run(); end end
  end

  // ------------------------------------------------------------------ operation interpreter
  int fd; string op; int line_no = 0;
  bit finished = 0;
  task automatic finish_run();
    if (finished) return;
    finished = 1;
    cp_close();
    if (q_pkt.size() != 0) begin errors++; $display("FAIL: %0d unexpected packet(s) from the DUT left at the end", q_pkt.size()); end
    $fdisplay(fd_bin, "#activity a_utmi_tx=%0d a_axis=%0d a_apb=%0d sof=%0d dmareq=%0d a_dmareq_checks=%0d", act_utmi_tx, act_axim, act_apb, sof_cnt, act_dmareq, act_dmareq_chk);
    $fclose(fd_bin);
    $display("ACTIVITY2 a_utmi_w16=%0d a_utmi_mode=%0d a_irq_level=%0d", act_utmi_w16, act_utmi_mode, act_irq_lvl); $display("ACTIVITY a_utmi_tx=%0d a_axim=%0d a_apb=%0d sof_cnt=%0d sof_min_ns=%0.1f sof_max_ns=%0.1f", act_utmi_tx, act_axim, act_apb, sof_cnt, sof_min, sof_max);
    if (nc_dead || nc_silent || nc_data || nc_mem) $display("NC dead=%0d silent=%0d data=%0d mem=%0d dut_packets=%0d data_flips=%0d mem_flips=%0d", nc_dead, nc_silent, nc_data, nc_mem, nc_pkt_n, nc_data_n, nc_mem_n);
    $display("PHY_ROW a_phy_row_cycles=%0d", act_phy_row);
    $display("UTMILP a_susp_handoff wakes=%0d handoffs=%0d spurious=%0d", act_wake, act_handoff, act_spur);   // UTMILP-LINE
    begin string cs = ""; foreach (chk_exec[ln]) cs = {cs, $sformatf(" %0d:%0d", ln, chk_exec[ln])}; $display("CHKEXEC%s", cs); end
    $display("CHECKPOINTS reached=%0d", cp_n);
    $display("RESULT %s checks=%0d errors=%0d", (errors == 0 && checks > 0) ? "PASS" : "FAIL", checks, errors);
    $finish;
  endtask
  function automatic int rdi(); int v; void'($fscanf(fd, "%h", v)); return v; endfunction

  initial begin
    byte unsigned b[]; byte unsigned p[]; bit got; int n, a, d, m, t, pid, k; string s; logic [15:0] c16; logic [18:0] f;
    if (!$value$plusargs("ops=%s", ops_file)) begin $display("FAIL: +ops missing"); $finish; end
    if (!$value$plusargs("out=%s", out_dir)) out_dir = ".";
    fd = $fopen(ops_file, "r"); if (fd == 0) begin $display("FAIL: cannot open %s", ops_file); $finish; end
    fd_bin = $fopen({out_dir, "/bins.txt"}, "w");
    for (int i = 0; i < 1048576; i++) mem[i] = 8'h00;
    repeat (8) @(posedge clk_bus); rst_n = 1; repeat (20) @(posedge clk_bus);
    while ($fscanf(fd, "%s", op) == 1) begin
      line_no++;
      case (op)
        "#": begin void'($fgets(s, fd)); end
        "W": begin a = rdi(); d = rdi(); apb_xfer(1, a[15:0], d, 4'hF, 3'd0); end
        "WS": begin a = rdi(); d = rdi(); m = rdi(); t = rdi(); k = rdi();           // write with strobe, prot, expected error
          apb_xfer(1, a[15:0], d, m[3:0], t[2:0]); chk(apb_err == k[0], $sformatf("line %0d: PSLVERR %b expected %b (write %04x)", line_no, apb_err, k[0], a)); end
        "R": begin a = rdi(); d = rdi(); m = rdi(); apb_xfer(0, a[15:0], 0, 4'h0, 3'd0);
          chk((apb_rdata & m) == (d & m), $sformatf("line %0d: read %04x = %08x expected %08x mask %08x", line_no, a, apb_rdata, d, m)); end
        "RANY": begin a = rdi(); m = rdi(); apb_xfer(0, a[15:0], 0, 4'h0, 3'd0);          // read: at least one bit of the mask is 1
          chk((apb_rdata & m) != 0, $sformatf("line %0d: read %04x = %08x has none of the bits %08x", line_no, a, apb_rdata, m)); end
        "RS": begin a = rdi(); d = rdi(); m = rdi(); t = rdi(); k = rdi();            // read with prot and expected error
          apb_xfer(0, a[15:0], 0, 4'h0, t[2:0]); chk(apb_err == k[0], $sformatf("line %0d: PSLVERR %b expected %b (read %04x)", line_no, apb_err, k[0], a));
          if (!k[0]) chk((apb_rdata & m) == (d & m), $sformatf("line %0d: read %04x = %08x expected %08x", line_no, a, apb_rdata, d)); end
        "P": begin a = rdi(); d = rdi(); m = rdi(); t = rdi(); k = 0; bus_free = 1;   // poll until (read & mask) == data
          do begin apb_xfer(0, a[15:0], 0, 4'h0, 3'd0); k++; if ((apb_rdata & m) != (d & m)) repeat (20) @(posedge clk_bus); end
          while ((apb_rdata & m) != (d & m) && k < t);
          bus_free = 0; wait (!busy_sof);
          chk((apb_rdata & m) == (d & m), $sformatf("line %0d: poll %04x = %08x expected %08x mask %08x after %0d reads", line_no, a, apb_rdata, d, m, k)); end
        "I": begin n = rdi(); bus_free = 1; repeat (n) @(posedge clk_phy); bus_free = 0; wait (!busy_sof); end
        "IB": begin n = rdi(); bus_free = 1; repeat (n) @(posedge clk_bus); bus_free = 0; wait (!busy_sof); end
        "RP": begin a = rdi(); apb_xfer(0, a[15:0], 0, 4'h0, 3'd0); $display("READ @%0t: %04x = %08x", $time, a, apb_rdata); end
        "PP": begin $display("PINS @%0t: mode=%02h (dmpd dppd susp_n term xcvr[1:0] op[1:0]) txvalid=%b linestate=%b int=%b", $time, {dmpd, dppd, suspend_n, termsel, xcvrsel, opmode}, utmi_txvalid, utmi_linestate, int_usb); end
        "ID": begin n = rdi(); repeat (n) @(posedge clk_phy); end      // delay inside a transaction: no keep-alive SOF
        "SG": begin d = rdi(); sof_period = rdi(); sofgen = d[0]; idle_cnt = 0; end
        "TK": begin pid = rdi(); a = rdi(); d = rdi(); m = rdi();                    // token: pid addr ep crc_flip
          f = 19'({d[3:0], a[6:0]}); b = new[3]; b[0] = pidb(pid[3:0]); b[1] = f[7:0];
          b[2] = {crc5_field(f, 11) ^ 5'(m), f[10:8]}; phy_send(b, 3, -1); end
        "DT": begin pid = rdi(); m = rdi(); n = rdi();                                // data: pid crc_flip len bytes
          p = new[n]; for (int i = 0; i < n; i++) p[i] = 8'(rdi());
          c16 = ~crc16_rem(p, n) ^ 16'(m); b = new[n + 3]; b[0] = pidb(pid[3:0]);
          for (int i = 0; i < n; i++) b[1 + i] = p[i];
          for (int i = 0; i < 8; i++) begin b[n + 1][i] = c16[15 - i]; b[n + 2][i] = c16[7 - i]; end
          phy_send(b, n + 3, -1); end
        "HS": begin pid = rdi(); b = new[1]; b[0] = pidb(pid[3:0]); phy_send(b, 1, -1); end
        "RXH": begin d = rdi(); n = rdi(); b = new[n]; for (int i = 0; i < n; i++) b[i] = 8'(rdi());   // n bytes, then RXActive held d cycles without data (stuck PHY)
          wait (!busy_sof); @(posedge clk_phy); utmi_rxactive <= 1;
          for (int i = 0; i < n; i++) begin utmi_datain <= {8'h00, b[i]}; utmi_rxvalid <= 1; @(posedge clk_phy); end
          utmi_rxvalid <= 0; repeat (d) @(posedge clk_phy); utmi_rxactive <= 0; t_rx_end = $realtime; repeat (ipg) @(posedge clk_phy); end
        "RAW": begin m = rdi(); n = rdi(); b = new[n]; for (int i = 0; i < n; i++) b[i] = 8'(rdi()); phy_send(b, n, m - 1); end
        "XH": begin pid = rdi(); t = rdi(); get_pkt(t, got, p);                        // expect handshake
          chk(got && p.size() == 1 && p[0] == pidb(pid[3:0]), $sformatf("line %0d: expected handshake PID %h, got %s", line_no, pid[3:0],
              got ? $sformatf("%0d byte(s), first %02x", p.size(), p[0]) : "nothing")); end
        "XD": begin pid = rdi(); t = rdi(); n = rdi(); b = new[n]; for (int i = 0; i < n; i++) b[i] = 8'(rdi());   // expect data packet
          get_pkt(t, got, p);
          chk(got && p.size() == n + 3 && p[0] == pidb(pid[3:0]), $sformatf("line %0d: expected data PID %h with %0d bytes, got %s", line_no, pid[3:0], n,
              got ? $sformatf("%0d byte(s), first %02x", p.size(), p[0]) : "nothing"));
          if (got && p.size() == n + 3) begin
            byte unsigned pl[]; k = 0; pl = new[n];
            for (int i = 0; i < n; i++) begin pl[i] = p[1 + i]; if (p[1 + i] != b[i]) k++; end
            chk(k == 0, $sformatf("line %0d: %0d payload byte(s) differ, got %02x %02x %02x %02x expected %02x %02x %02x %02x", line_no, k, n > 0 ? p[1] : 8'h0, n > 1 ? p[2] : 8'h0, n > 2 ? p[3] : 8'h0, n > 3 ? p[4] : 8'h0, n > 0 ? b[0] : 8'h0, n > 1 ? b[1] : 8'h0, n > 2 ? b[2] : 8'h0, n > 3 ? b[3] : 8'h0));
            c16 = ~crc16_rem(pl, n); k = 0;
            for (int i = 0; i < 8; i++) if (p[n + 1][i] != c16[15 - i] || p[n + 2][i] != c16[7 - i]) k++;
            chk(k == 0, $sformatf("line %0d: CRC16 of the DUT packet wrong", line_no));
          end end
        "XT": begin pid = rdi(); a = rdi(); d = rdi(); t = rdi(); get_pkt(t, got, p);  // expect token: pid addr ep
          f = 19'({d[3:0], a[6:0]});
          chk(got && p.size() == 3 && p[0] == pidb(pid[3:0]) && p[1] == f[7:0] && p[2] == {crc5_field(f, 11), f[10:8]},
              $sformatf("line %0d: expected token PID %h addr %0d ep %0d, got %s", line_no, pid[3:0], a, d,
              got ? $sformatf("%0d byte(s): %02x %02x %02x", p.size(), p[0], p.size() > 1 ? p[1] : 8'h0, p.size() > 2 ? p[2] : 8'h0) : "nothing")); end
        "XC": begin a = rdi(); d = rdi(); m = rdi(); t = rdi(); get_pkt(t, got, p); k = 0;   // expect a chirp or resume stream: min max value tmo
          if (got) for (int i = 0; i < p.size(); i++) if (p[i] != 8'(m)) k++;
          chk(got && k == 0 && p.size() >= a && p.size() <= d, $sformatf("line %0d: expected a stream of %02x with %0d..%0d bytes, got %s", line_no, m, a, d,
              got ? $sformatf("%0d byte(s), %0d different", p.size(), k) : "nothing")); end
        "XK": begin a = rdi(); d = rdi(); m = rdi(); t = rdi(); get_pkt(t, got, p); k = 0; n = 0;   // expect alternating chirps: min max min_transitions tmo
          if (got) begin
            for (int i = 0; i < p.size(); i++) if (p[i] != 8'h00 && p[i] != 8'hFF) k++;
            for (int i = 1; i < p.size(); i++) if (p[i] != p[i-1]) n++;
          end
          chk(got && k == 0 && p.size() >= a && p.size() <= d && n >= m, $sformatf("line %0d: expected alternating K/J chirp, %0d..%0d bytes, >= %0d transitions; got %s", line_no, a, d, m,
              got ? $sformatf("%0d byte(s), %0d odd, %0d transitions", p.size(), k, n) : "nothing")); end
        "XS": begin a = rdi(); d = rdi(); m = rdi(); t = rdi(); k = rdi(); n = rdi(); pid = rdi(); get_pkt(pid, got, p);   // expect a SPLIT token: hub sc port s e et tmo
          f = 19'(a[6:0]) | (19'(d[0]) << 7) | (19'(m[6:0]) << 8) | (19'(t[0]) << 15) | (19'(k[0]) << 16) | (19'(n[1:0]) << 17);
          chk(got && p.size() == 4 && p[0] == pidb(4'h8) && p[1] == f[7:0] && p[2] == f[15:8] && p[3] == {crc5_field(f, 19), f[18:16]},
              $sformatf("line %0d: expected SPLIT token hub %0d sc %0d port %0d s %0d e %0d et %0d, got %s", line_no, a, d[0], m, t[0], k[0], n[1:0],
              got ? $sformatf("%0d byte(s): %02x %02x %02x %02x", p.size(), p[0], p.size() > 1 ? p[1] : 8'h0, p.size() > 2 ? p[2] : 8'h0, p.size() > 3 ? p[3] : 8'h0) : "nothing")); end
        "XN": begin t = rdi(); get_pkt(t, got, p); chk(!got, $sformatf("line %0d: expected no packet, got %0d byte(s) first %02x", line_no, got ? p.size() : 0, got ? p[0] : 8'h0)); end
        "GAPB": begin a = rdi(); d = rdi(); chk(last_gap >= 100000 && last_gap - 100000 >= a && last_gap - 100000 <= d, $sformatf("line %0d: gap to the previous own packet %0d cycles outside [%0d, %0d]", line_no, last_gap - 100000, a, d)); end
        "GAP": begin a = rdi(); d = rdi(); chk(last_gap >= a && last_gap <= d, $sformatf("line %0d: response gap %0d cycles outside [%0d, %0d]", line_no, last_gap, a, d)); end
        "MW": begin a = rdi(); n = rdi(); for (int i = 0; i < n; i++) mem[a + i] = 8'(rdi()); end
        "MC": begin a = rdi(); n = rdi(); k = 0; for (int i = 0; i < n; i++) begin d = rdi(); if (mem[a + i] != 8'(d)) begin k++; if (k == 1) m = i; end end
          chk(k == 0, $sformatf("line %0d: memory at %05x: %0d byte(s) differ, first at offset %0d", line_no, a, k, m)); end
        "LS": begin d = rdi(); ls_auto = 0; utmi_linestate <= d[1:0]; end
        "LSR": begin a = rdi(); d = rdi();                                                 // line state that the PHY row gives with the attached
          k = (xcvrsel == 2'b00 && !termsel && opmode != 2'b01 && dppd && dmpd) ? 0 : ((d == 2) ? 2 : 1);   // device (d: 1 pull-up on D+, 2 on D-):
          chk(k == a, $sformatf("line %0d: the PHY row xcvr %b term %b opmode %b gives line state %0d, expected %0d", line_no, xcvrsel, termsel, opmode, k, a));
          utmi_linestate <= k[1:0]; ls_dev = d; ls_auto = 1; end                        // SE0 only under the high-speed terminations;
                                                                                       // from now on the line follows the row (until LS)
        "PIN": begin a = rdi(); d = rdi();
          case (a) 0: vbusvalid <= d[0]; 1: iddig <= d[0]; 2: hostdisc <= d[0]; 3: ovrcur_n <= d[0]; 4: slverr_en <= d[0]; 5: protect_en <= d[0];
            6: sessend <= d[0]; 7: avalid <= d[0]; 8: bvalid_pin <= d[0]; default: ; endcase end
        "XP": begin a = rdi(); d = rdi(); m = rdi();                                   // expect output pins: group value mask
          case (a)
            0: k = {dmpd, dppd, suspend_n, termsel, xcvrsel, opmode};
            1: k = {int_usb};
            2: k = {drvvbus, vbus_pwr_en};
            3: k = {utmi_txvalid};
            default: k = 0;
          endcase
          chk((k & m) == (d & m), $sformatf("line %0d: pin group %0d = %0h expected %0h mask %0h", line_no, a, k, d, m)); end
        "WP": begin a = rdi(); d = rdi(); m = rdi(); t = rdi(); k = 0;                  // wait for pins: group value mask timeout(phy cycles)
          n = 0;
          while (n < t) begin
            case (a) 0: k = {dmpd, dppd, suspend_n, termsel, xcvrsel, opmode}; 1: k = {int_usb}; 2: k = {drvvbus, vbus_pwr_en}; 3: k = {utmi_txvalid}; default: k = 0; endcase
            if ((k & m) == (d & m)) break;
            @(posedge clk_phy); n++;
          end
          chk((k & m) == (d & m), $sformatf("line %0d: pin group %0d did not reach %0h (mask %0h) in %0d cycles, last %0h", line_no, a, d, m, t, k)); last_gap = n; end
        "BP": begin bp_pct = rdi(); end
        "TXR": begin txready_low = rdi(); end
        "AXE": begin a = rdi(); d = rdi(); m = rdi(); if (a == 0) err_wr_at = d; else err_rd_at = d; err_code = m; end
        "WIN": begin win_lo = rdi(); win_hi = rdi(); win_on = 1; end
        "PCLKA": begin d = rdi(); pclk_auto = d[0]; end
        "PCLK": begin d = rdi(); pclk_on = d[0]; end
        "PCLKD": begin d = rdi(); pclk_dly = real'(d); end                                // PHY clock restart delay in ns (DEC-049)
        "XWAKE": begin a = rdi(); d = rdi(); chk(act_wake == a && act_spur >= d, $sformatf("line %0d: utmilp wakes %0d spurious %0d, expected exactly %0d wakes and at least %0d spurious", line_no, act_wake, act_spur, a, d)); end   // UTMILP-LINE SVA-017 activity: exact wake count
        "CLK": begin d = rdi(); t_bus = real'(d) / 100.0; end
        "RST": begin d = rdi(); rst_n = 0; repeat (d) @(posedge clk_bus); rst_n = 1; repeat (20) @(posedge clk_bus); end
        "IPG": begin ipg = rdi(); end
        "SOF": begin a = rdi(); d = rdi(); m = rdi();                                    // SOF packets since the previous SOF operation >= a, interval in [d, m] ns
          // 2026-11-24 oracle audit: the count was cumulative from the start of the run, so "at least one SOF after the resume"
          // was always true; the interval window was not checked with fewer than two SOF packets.
          chk(sof_cnt - sof_base >= a, $sformatf("line %0d: %0d SOF packets since the previous SOF check, expected at least %0d", line_no, sof_cnt - sof_base, a));
          if (sof_cnt - sof_base >= 2) chk(sof_min >= real'(d) && sof_max <= real'(m), $sformatf("line %0d: SOF interval %0.1f..%0.1f ns outside [%0d, %0d]", line_no, sof_min, sof_max, d, m));
          sof_base = sof_cnt; sof_min = 1e12; sof_max = 0; sof_t_last = 0; end
        "SOFW": begin a = rdi();                                                           // frame number sequence ok and at least a roll-overs since the last SOFW (a = 0: restart)
          if (a > 0) begin
            chk(sof_seq_err == 0, $sformatf("line %0d: %0d SOF frame number jumps", line_no, sof_seq_err));
            chk(sof_wrap >= a, $sformatf("line %0d: %0d frame number roll-overs, expected at least %0d", line_no, sof_wrap, a));
          end
          sof_seq_err = 0; sof_wrap = 0; sof_fn = -1; end
        "NSOF": begin d = rdi(); a = sof_cnt; sof_mark = sof_cnt; repeat (d) @(posedge clk_phy);                // no SOF packet for d CLK-PHY cycles
          chk(sof_cnt == a, $sformatf("line %0d: %0d SOF packets in a window without SOF", line_no, sof_cnt - a)); end
        "SOFR": begin a = rdi();                                                           // at least a SOF packets since the last NSOF
          chk(sof_cnt - sof_mark >= a, $sformatf("line %0d: %0d SOF packets since the window, expected at least %0d", line_no, sof_cnt - sof_mark, a)); end
        "WSOF": begin d = rdi(); a = sof_cnt + d; k = q_pkt.size();                     // wait for d more SOF packets; no other packet may appear meanwhile
          while (sof_cnt < a) @(posedge clk_phy);
          chk(q_pkt.size() == k, $sformatf("line %0d: %0d unexpected packet(s) while waiting for %0d SOF packets", line_no, q_pkt.size() - k, d)); end
        "SOFT": begin sof_tref = sof_t_last; sof_tfirst = 0; sof_want = 1; end                // reference: the last SOF so far; record the next one
        "SOFQ": begin d = rdi(); m = rdi(); begin real dt, e; int k; dt = sof_tfirst - sof_tref; k = $rtoi(dt / d + 0.5); e = dt - k * d;
          chk(sof_tfirst > 0 && e <= m && e >= -m, $sformatf("line %0d: first SOF after the reference is %0.1f ns later: %0d periods %0.1f ns off (limit %0d)", line_no, dt, k, e, m)); end end
        "TM": begin t_mark = $realtime; end                                               // mark the time
        "TC": begin a = rdi(); d = rdi(); n = int'(($realtime - t_mark) / T_PHY);           // CLK-PHY cycles since the mark in [a, d]
          chk(n >= a && n <= d, $sformatf("line %0d: %0d CLK-PHY cycles since the time mark, expected %0d to %0d", line_no, n, a, d)); end
        "SOFM": begin sof_mk2 = sof_cnt; end                                               // mark the SOF count
        "SOFD": begin a = rdi(); d = rdi();                                                 // SOF packets since the mark are in [a, d]
          chk(sof_cnt - sof_mk2 >= a && sof_cnt - sof_mk2 <= d, $sformatf("line %0d: %0d SOF packets since the mark, expected %0d to %0d", line_no, sof_cnt - sof_mk2, a, d)); end
        "KSOF": begin d = rdi(); keep_sof = d[0]; end
        "FLUSH": begin repeat (4) @(posedge clk_phy); q_pkt.delete(); q_t0.delete(); q_gap.delete(); end
        "AW": begin int bu, ad, nb, ex; bu = rdi(); ad = rdi(); nb = rdi(); ex = rdi(); ax_data.delete(); for (int i = 0; i < nb; i++) ax_data.push_back(rdi()); ax_write(bu, ad, nb, ex, ax_data); end
        "AWN": begin   // write burst launched in the background (it may stall on a full region); joined by AWJ
          int bu, ad, nb, ex; int unsigned dq [$]; bu = rdi(); ad = rdi(); nb = rdi(); ex = rdi(); for (int i = 0; i < nb; i++) dq.push_back(rdi());
          ax_bg_busy++; ax_bg_done = 0;
          fork begin int unsigned c [$]; c = dq; ax_write(bu, ad, nb, ex, c, 200000); ax_bg_busy--; ax_bg_done = 1; end join_none
        end
        "AWS": begin int w; w = rdi(); repeat (w) @(posedge clk_bus); chk(ax_bg_busy != 0, $sformatf("line %0d: the background write finished although the region is full", line_no)); end
        "AWJ": begin int w; w = rdi(); for (int i = 0; i < w && ax_bg_busy != 0; i++) @(posedge clk_bus); chk(ax_bg_busy == 0, $sformatf("line %0d: the background write did not finish within %0d bus cycles", line_no, w)); end
        "AR": begin int bu, ad, nb, ex; bu = rdi(); ad = rdi(); nb = rdi(); ex = rdi(); ax_data.delete(); if (ex == 0) for (int i = 0; i < 2 * nb; i++) ax_data.push_back(rdi()); ax_read(bu, ad, nb, ex); end
        "DR": begin int ch, v, tm; bit ok; ch = rdi(); v = rdi(); tm = rdi(); ok = 0; for (int i = 0; i < tm && !ok; i++) begin @(posedge clk_bus); ok = (dma_req[ch] == v[0]); end
                chk(ok, $sformatf("line %0d: o_dma_req[%0d] did not reach %0d within %0d bus cycles", line_no, ch, v, tm)); act_dmareq++; end
        "DX": begin int ch, v; ch = rdi(); v = rdi(); @(posedge clk_bus); chk(dma_req[ch] == v[0], $sformatf("line %0d: o_dma_req[%0d] is %0b, expected %0d", line_no, ch, dma_req[ch], v)); act_dmareq++; end
        "DA": begin int ch; ch = rdi(); @(posedge clk_bus); dma_ack[ch] <= 1; @(posedge clk_bus); dma_ack[ch] <= 0; act_dmareq++; end
        "WD": begin d = rdi(); wd_limit = longint'(d) * 64'd1000000; end
        "B": begin void'($fscanf(fd, "%s", s)); $fdisplay(fd_bin, "%s %0d", s, errors); end
        "CHK": begin void'($fscanf(fd, "%s", s)); cp_close(); cp_id = s; cp_base = checks; cp_n++; $display("CHKPT @%0t: %s", $time, s); end
        "MSG": begin void'($fgets(s, fd)); $display("MSG @%0t:%s", $time, s.substr(0, s.len() - 2)); end
        "END": begin finish_run(); end
        default: begin errors++; $display("FAIL: unknown operation '%s' at item %0d", op, line_no); finish_run(); end
      endcase
    end
    finish_run();
  end
endmodule
